import{ref}from"vue";import{defineStore}from"pinia";import{useToast}from"vue-toast-notification";import"vue-toast-notification/dist/theme-sugar.css";export const useCustomStore=defineStore("custom",()=>{const isShowPass=ref(!1),$toast=useToast(),showPassHandler=()=>{isShowPass.value=!isShowPass.value},toast=(message,type)=>{"success"==type?$toast.success(message,{position:"top-left",duration:4e3}):"info"==type?$toast.info(message,{position:"top-left",duration:4e3}):$toast.error(message,{position:"top-left",duration:4e3})};return{isShowPass:isShowPass,showPassHandler:showPassHandler,toast:toast}});